import json, glob
from arena_kit.cost import total_cost, cost_breakdown
cases={c['case_id']:c for c in json.load(open('logs/cases/practice.json'))}
# standard-filled deal terms from the best session per case; recompute implied prices
best={}
for f in glob.glob('logs/sessions/practice/P*.json'):
    d=json.load(open(f)); r=d.get('result') or {}
    if not r.get('deal'): continue
    cid=d['case_id']
    if cid not in best or r['score']>best[cid]['score']: best[cid]=r
records={'P01':0.998,'P02':0.847,'P03':0.936,'P04':0.874,'P05':0.924,'P07':0.812,'P08':0.916,'P10':0.702,'P11':0.807,'P18':0.677}
def price_for(case, terms, target):
    lo,hi=0.0,1000.0
    for _ in range(60):
        mid=(lo+hi)/2
        if total_cost(case,{**terms,'unit_price':mid})>target: hi=mid
        else: lo=mid
